uint256 newBalanceToken0 = IBEP20(usdtAddress).balanceOf(address(this));
half = newBalanceToken0.sub(initialBalanceToken0);

addLiquidity(address(cfTokenAddress), otherHalf, usdtAddress, half, toAddress);
}

