uint256 tokenAmount,
address to,
address usdtAddress
) private lockTheSwap{

address[] memory path = new address[](2);
path[0] = address(cfTokenAddress);
path[1] = usdtAddress;
IBEP20(address(cfTokenAddress)).approve(address(router), tokenAmount);

router.swapExactTokensForTokensSupportingFeeOnTransferTokens(
tokenAmount,
0,
path,
address(this),
block.timestamp
);
